function Xg = gradient_dke_jd(Xf,dx,opt)% calculates the derivative of the multidimentional matrix along the colomns. % The derivatives are taken at the center of cells. Zeros can be added at the % beginning (opt = 1), at the end (opt = 2) or at both (opt = 3)% %by Joan Decker%modified by Y. Peysson, CEA-DRFC 03/12/2002 (yves.peysson@cea.fr)%Sf = size(Xf);N = Sf(1);dim = length(size(Xf));if N == 1, Xg = zeros(size(Xf));break,end%if (size(dx,1) + size(dx,2)) == 2,%dx is a scalar (for p at present time)	Xd = diff(Xf)./dx;%else		Xd = diff(Xf)./dx(1:N-1,:);%dx is a matrix (for mhu)end%if opt == 1,    Xg = zeros([N,Sf(2:dim)]);    Xg(2:N,:) = Xd;elseif opt == 2,    Xg = zeros([N,Sf(2:dim)]);    Xg(1:N-1,:) = Xd;elseif opt == 3,    Xg = zeros([N+1,Sf(2:dim)]);    Xg(2:N,:) = Xd;else     Xg = Xd;end    